import React from 'react';
import { Package, Edit, Trash2 } from 'lucide-react';

const ProductsGrid = () => {
  const [products] = React.useState([
    { id: 1, name: 'iPhone 14 Pro', category: 'Électronique', price: '$999', stock: 45, status: 'in_stock' },
    { id: 2, name: 'MacBook Air M2', category: 'Informatique', price: '$1,199', stock: 12, status: 'low_stock' },
    { id: 3, name: 'AirPods Pro', category: 'Audio', price: '$249', stock: 89, status: 'in_stock' },
    { id: 4, name: 'Apple Watch Series 8', category: 'Wearables', price: '$399', stock: 0, status: 'out_of_stock' },
    { id: 5, name: 'iPad Pro', category: 'Tablettes', price: '$1,099', stock: 23, status: 'in_stock' },
  ]);

  const getStatusBadge = (status) => {
    switch (status) {
      case 'in_stock':
        return { text: 'En stock', className: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400' };
      case 'low_stock':
        return { text: 'Stock faible', className: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400' };
      case 'out_of_stock':
        return { text: 'Rupture', className: 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400' };
      default:
        return { text: 'Inconnu', className: 'bg-neutral-100 text-neutral-800 dark:bg-neutral-800 dark:text-neutral-400' };
    }
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
      {products.map((product) => {
        const statusBadge = getStatusBadge(product.status);

        return (
          <div key={product.id} className="bg-gradient-to-br from-white to-white/70 dark:from-neutral-900 dark:to-neutral-900/70 backdrop-blur-xl rounded-2xl p-6 shadow-lg border border-white/30 dark:border-neutral-800/50 hover:scale-[1.02] transition-transform duration-300">
            <div className="flex items-start justify-between mb-4">
              <div className="h-16 w-16 rounded-xl bg-gradient-to-r from-primary-500/10 to-secondary-500/10 flex items-center justify-center">
                <Package className="h-8 w-8 text-primary-500" />
              </div>
              <span className={`px-3 py-1 rounded-full text-xs font-medium ${statusBadge.className}`}>
                {statusBadge.text}
              </span>
            </div>
            <h3 className="text-lg font-bold text-neutral-900 dark:text-white mb-2">{product.name}</h3>
            <p className="text-sm text-neutral-600 dark:text-neutral-400 mb-4">{product.category}</p>
            <div className="flex items-center justify-between">
              <div>
                <p className="text-2xl font-bold text-primary-600 dark:text-primary-400">{product.price}</p>
                <p className="text-xs text-neutral-500 dark:text-neutral-500">{product.stock} unités</p>
              </div>
              <div className="flex items-center space-x-2">
                <button className="p-2 text-neutral-500 hover:text-primary-600 dark:hover:text-primary-400 transition-colors">
                  <Edit className="h-4 w-4" />
                </button>
                <button className="p-2 text-neutral-500 hover:text-red-600 dark:hover:text-red-400 transition-colors">
                  <Trash2 className="h-4 w-4" />
                </button>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default ProductsGrid;
